// Analyze which padding rule satisfies all test cases in transpose.spec.js
import { readFileSync } from 'node:fs';

const src = readFileSync(new URL('./transpose.spec.js', import.meta.url), 'utf8');

// Extract test cases: name, input array, expected array
const cases = [];
const testRe = /test\('([^']+)',\s*\(\)\s*=>\s*\{([\s\S]*?)\n  \}\);/g;
let m;
while ((m = testRe.exec(src))) {
  const name = m[1];
  const body = m[2];
  const arrRe = /(?:const input = |const expected = )\[(?:[\s\S]*?)\];/g;
  const arrays = [];
  let am;
  while ((am = arrRe.exec(body))) arrays.push(eval(am[0].replace(/^const \w+ = /, '')));
  cases.push({ name, input: arrays[0], expected: arrays[1] });
}

const simple = (lines) => {
  const width = Math.max(0, ...lines.map((l) => l.length));
  return Array.from({ length: width }, (_, c) => lines.map((l) => l[c] ?? ' ').join(''));
};

// R2: rstrip all trailing spaces
const rstripAll = (lines) => simple(lines).map((r) => r.replace(/ +$/, ''));

// R3: trim only trailing spaces that came from padding (row shorter than col)
const trimPad = (lines) => {
  const width = Math.max(0, ...lines.map((l) => l.length));
  return Array.from({ length: width }, (_, c) => {
    let last = -1;
    lines.forEach((l, i) => { if (c < l.length) last = i; });
    return lines.slice(0, last + 1).map((l) => (c < l.length ? l[c] : ' ')).join('');
  });
};

// R4: like R3 but only trim when the last row is shorter than the longest row
const trimPadIfLastShort = (lines) => {
  const maxLen = Math.max(0, ...lines.map((l) => l.length));
  const lastShort = lines.length > 0 && lines[lines.length - 1].length < maxLen;
  return lastShort ? trimPad(lines) : simple(lines);
};

for (const [label, fn] of [
  ['simple(no trim)', simple],
  ['rstripAll', rstripAll],
  ['trimPad', trimPad],
  ['trimPadIfLastShort', trimPadIfLastShort],
]) {
  const fails = cases.filter((c) => JSON.stringify(fn(c.input)) !== JSON.stringify(c.expected)).map((c) => c.name);
  console.log(`${label}: ${fails.length === 0 ? 'ALL PASS' : 'fails: ' + fails.join(', ')}`);
}

